497	func TestConcurrentSameDevice(t *testing.T) {
498		s, _ := openTemp(t)
499		mustRegister(t, s, "dev-1", "1.0")
500		const n = 20
501		var wg sync.WaitGroup
502		// 并发提交相同修订号：只有一个能成功
503		results := make(chan error, n)
504		for i := 0; i < n; i++ {
505			wg.Add(1)
506			go func(i int) {
507				defer wg.Done()
508				cfg, _ := json.Marshal(map[string]int{"i": i})
509				_, err := s.UpdateDesired("dev-1", "op", base, 0, cfg)
510				results <- err
511			}(i)
512		}
513		wg.Wait()
514		close(results)
515		var ok, conflict int
516		for err := range results {
517			if err == nil {
518				ok++
519			} else if errors.Is(err, ErrRevisionConflict) {
520				conflict++
521			}
522		}
523		if ok != 1 || conflict != n-1 {
524			t.Fatalf("revision race: ok=%d conflict=%d", ok, conflict)
525		}
526		// 并发上报同一序号：只有一个不同内容的能成功
527		results = make(chan error, n)
528		for i := 0; i < n; i++ {
529			wg.Add(1)
530			go func(i int) {
531				defer wg.Done()
532				cfg, _ := json.Marshal(map[string]int{"r": i})
533				results <- s.Report("dev-1", 1, base, "1.1", cfg)
534			}(i)
535		}
536		wg.Wait()
537		close(results)
538		ok, conflict = 0, 0
539		for err := range results {
540			if err == nil {
541				ok++
542			} else if errors.Is(err, ErrReportConflict) {
543				conflict++
544			}
545		}
546		if ok != 1 || conflict != n-1 {
547			t.Fatalf("report race: ok=%d conflict=%d", ok, conflict)
548		}
549		v, _ := s.Get("dev-1")
550		if v.Revision != 1 || v.LastSeq != 1 {
551			t.Fatalf("final state: %+v", v)
552		}
553	}
