179	// 实际差异缺时间、残留无差异路径、时间为零、父路径代替子路径、
180	// 条数相同但路径不同：都必须返回 ErrCorruptStorage 拒绝打开整个存储，
181	// 且原文件内容保持不变，不补当前时间、不删多余记录、不重写配置。
182	func TestRestoreDiffSinceCorruptRefused(t *testing.T) {
183		cases := map[string]func(fixStore){
184			// 实际存在 /wifi/ssid 差异，却完全没有计时记录。
185			"missing time record": func(doc fixStore) {
186				d := doc.Devices["dev-1"]
187				d.DiffSince = nil
188				doc.Devices["dev-1"] = d
189			},
190			// 已相等的 /mode 仍残留时间记录。
191			"stale record for equal path": func(doc fixStore) {
192				d := doc.Devices["dev-1"]
193				d.DiffSince["/mode"] = "2026-10-02T12:00:00Z"
194				doc.Devices["dev-1"] = d
195			},
196			// 只残留无关路径，实际差异反而没有记录。
197			"only stale record": func(doc fixStore) {
198				d := doc.Devices["dev-1"]
199				d.DiffSince = map[string]string{"/mode": "2026-10-02T12:00:00Z"}
200				doc.Devices["dev-1"] = d
201			},
202			// 路径正确但时间为零值。
203			"zero first-seen time": func(doc fixStore) {
204				d := doc.Devices["dev-1"]
205				d.DiffSince = map[string]string{"/wifi/ssid": "0001-01-01T00:00:00Z"}
206				doc.Devices["dev-1"] = d
207			},
208			// 父路径 /wifi 的时间不能替代子路径 /wifi/ssid（条数相同）。
209			"parent path cannot cover child": func(doc fixStore) {
210				d := doc.Devices["dev-1"]
211				d.DiffSince = map[string]string{"/wifi": "2026-10-02T12:00:00Z"}
212				doc.Devices["dev-1"] = d
213			},
214			// 记录条数与差异条数相同，但路径对不上。
215			"same count different path": func(doc fixStore) {
216				d := doc.Devices["dev-1"]
217				d.DiffSince = map[string]string{"/wifi/chan": "2026-10-02T12:00:00Z"}
218				doc.Devices["dev-1"] = d
219			},
220		}
221		for name, mutate := range cases {
222			t.Run(name, func(t *testing.T) {
223				doc := diffSinceDoc()
224				mutate(doc)
225				dir, original := writeFixStore(t, doc)
226				s, err := Open(dir)
227				if err == nil {
228					s.Close()
229					t.Fatalf("expected ErrCorruptStorage")
230				}
231				if !errors.Is(err, ErrCorruptStorage) {
232					t.Fatalf("error must wrap ErrCorruptStorage: %v", err)
233				}
234				data, rerr := os.ReadFile(filepath.Join(dir, storeFileName))
235				if rerr != nil {
236					t.Fatal(rerr)
237				}
238				if string(data) != string(original) {
239					t.Fatalf("corrupt file modified on rejected open")
240				}
241			})
242		}
243	
244		// 没有差异的设备保存了时间记录同样损坏。
245		t.Run("record on device without diffs", func(t *testing.T) {
246			doc := fixStore{Format: 1, Devices: map[string]fixState{
247				"dev-1": {
248					Version:   "1.0",
249					Revision:  1,
250					Desired:   json.RawMessage(`{"a":1}`),
251					Reported:  json.RawMessage(`{"a":1}`),
252					DiffSince: map[string]string{"/a": "2026-10-02T12:00:00Z"},
253					Audit: []fixAudit{
254						{Operator: "op", Time: "2026-10-02T12:00:00Z", Revision: 1,
255							Before: json.RawMessage(`{}`), After: json.RawMessage(`{"a":1}`)},
256					},
257				},
258			}}
259			dir, original := writeFixStore(t, doc)
260			if _, err := Open(dir); !errors.Is(err, ErrCorruptStorage) {
261				t.Fatalf("stale time on equal device must be refused: %v", err)
262			}
263			if data, _ := os.ReadFile(filepath.Join(dir, storeFileName)); string(data) != string(original) {
264				t.Fatalf("corrupt file modified on rejected open")
265			}
266		})
267	}
268	
269	// 一台设备的计时记录损坏即拒绝打开整个存储，其他设备再正常也不可只跳过坏设备。
270	func TestRestoreDiffSinceOneBadDeviceRejectsAll(t *testing.T) {
271		doc := diffSinceDoc() // dev-1 合法
272		doc.Devices["good"] = fixState{
273			Version:  "1.0",
274			Desired:  json.RawMessage(`{}`),
275			Reported: json.RawMessage(`{}`),
276		}
277		bad := diffSinceDoc().Devices["dev-1"]
278		bad.DiffSince = nil // dev-2 有 /wifi/ssid 差异但缺时间记录
279		doc.Devices["bad"] = bad
280		dir, _ := writeFixStore(t, doc)
281		if _, err := Open(dir); !errors.Is(err, ErrCorruptStorage) {
282			t.Fatalf("whole store must be refused when one device lacks diff times: %v", err)
283		}
284	}
285	
286	// 跨关闭重开的计时生命周期：同一路径持续不同保留原时间；差异消失后再次出现
287	// 才重新计时，且恢复出的计时记录与正常流程产生的记录行为一致。
288	func TestRestoreDiffSinceLifecycleAcrossReopen(t *testing.T) {
289		t1 := base
290		s, dir := openTemp(t)
291		mustRegister(t, s, "dev-1", "1.0")
292		if _, err := s.UpdateDesired("dev-1", "op", t1, 0, json.RawMessage(`{"a":1}`)); err != nil {
293			t.Fatal(err)
294		}
295		if err := s.Close(); err != nil {
296			t.Fatal(err)
297		}
298	
299		// 重开后同一路径仍不同：保留首次时间。
300		s2, err := Open(dir)
301		if err != nil {
302			t.Fatalf("reopen with diff: %v", err)
303		}
304		if diffs, _ := s2.Diff("dev-1"); len(diffs) != 1 || !diffs[0].Since.Equal(t1) {
305			t.Fatalf("diff time must survive reopen: %+v", diffs)
306		}
307		// 重开后继续改值但仍不相等：沿用原时间。
308		t2 := base.Add(time.Minute)
309		if _, err := s2.UpdateDesired("dev-1", "op", t2, 1, json.RawMessage(`{"a":2}`)); err != nil {
310			t.Fatal(err)
311		}
312		if diffs, _ := s2.Diff("dev-1"); !diffs[0].Since.Equal(t1) {
313			t.Fatalf("persistent diff must keep original time: %+v", diffs)
314		}
315		// 差异消失，关闭重开：无差异、无计时记录仍合法。
316		t3 := base.Add(2 * time.Minute)
317		if err := s2.Report("dev-1", 1, t3, "1.0", json.RawMessage(`{"a":2}`)); err != nil {
318			t.Fatal(err)
319		}
320		if err := s2.Close(); err != nil {
321			t.Fatal(err)
322		}
323		s3, err := Open(dir)
324		if err != nil {
325			t.Fatalf("reopen without diffs: %v", err)
326		}
327		if diffs, _ := s3.Diff("dev-1"); len(diffs) != 0 {
328			t.Fatalf("cleared diff must stay cleared: %+v", diffs)
329		}
330		// 同一路径再次出现差异：必须重新计时，不能沿用消失前的 t1。
331		t4 := base.Add(3 * time.Minute)
332		if _, err := s3.UpdateDesired("dev-1", "op", t4, 2, json.RawMessage(`{"a":3}`)); err != nil {
333			t.Fatal(err)
334		}
335		if err := s3.Close(); err != nil {
336			t.Fatal(err)
337		}
338		s4, err := Open(dir)
339		if err != nil {
340			t.Fatalf("final reopen: %v", err)
341		}
342		defer s4.Close()
343		diffs, _ := s4.Diff("dev-1")
344		if len(diffs) != 1 || diffs[0].Path != "/a" || !diffs[0].Since.Equal(t4) {
345			t.Fatalf("reappeared diff must restart timing at t4: %+v", diffs)
346		}
347	}
